"""Fail-closed generated byte/ownership/path guards with synthetic public bytes."""

# Repeat exact public pins in isolated adversarial fixtures rather than weakening specs.
# pylint: disable=duplicate-code

import hashlib
import importlib
import json
import sys
from pathlib import Path

import pytest

sys.path.insert(0, str(Path(__file__).resolve().parents[2] / "scripts"))
recovery = importlib.import_module("colab_api_recovery")


@pytest.fixture(name="restored")
def restored_fixture(tmp_path, monkeypatch):
    spec = recovery.RecoverySpec("runtimes/new-runtime", "new-recovery-run")
    binding = {
        "runtime": spec.runtime,
        "run_name": spec.run_name,
        "sha256": recovery.ARCHIVE_SHA,
        "recovery_sha256": spec.sha256(),
    }
    paths = {
        key: str(tmp_path / key)
        for key in ("package", "venv", "private", "archive", "result", "root")
    }
    c = recovery.context(binding, **paths)
    p, s = c["paths"], c["spec"]
    package = Path(p["package"])
    package.mkdir()
    (package / "tools").mkdir()
    (package / "manifest.json").write_bytes(b"{}")
    Path(p["archive"]).write_bytes(b"archive")
    s["archive_sha256"] = hashlib.sha256(b"archive").hexdigest()
    s["manifest_sha256"] = hashlib.sha256(b"{}").hexdigest()
    target = Path(p["target"])
    target.mkdir(parents=True)
    Path(p["snapshot"]).write_bytes(b"opaque")
    s["snapshot_sha256"] = hashlib.sha256(b"opaque").hexdigest()
    s["bytes"] = 6
    row = {"step": 46500, "path": "step_00046500.pt", "sha256": s["snapshot_sha256"]}
    identity = {
        "schema_version": 1,
        "run": s["origin_run"],
        "package_manifest_sha256": s["manifest_sha256"],
        "source_sha256": s["source_sha256"],
        "data_fingerprint": s["data_fingerprint"],
    }
    metadata = {"identity": identity, "owned": [row], "nonce": "a" * 32}
    (target / "latest.json").write_text(json.dumps(row))
    (target / "backup.json").write_text(json.dumps(metadata))
    package_module = importlib.import_module("colab_package")
    monkeypatch.setattr(package_module, "verify_directory", lambda _path: {})
    namespace = {}
    exec(recovery.READBACK_SOURCE, namespace)  # pylint: disable=exec-used
    namespace["source_check"](c)
    namespace["snapshot_check"](c)
    return c, namespace, metadata, row


@pytest.mark.parametrize(
    "damage", ["bytes", "owned", "order", "latest", "identity", "extra", "nonce"]
)
def test_snapshot_guard_rejects_wrong_bytes_and_ownership(restored, damage):
    c, namespace, metadata, row = restored
    target = Path(c["paths"]["target"])
    if damage == "bytes":
        Path(c["paths"]["snapshot"]).write_bytes(b"broken")
    elif damage == "owned":
        metadata["owned"] = []
    elif damage == "order":
        metadata["owned"] = [row, row]
    elif damage == "latest":
        row = dict(row, step=46375)
    elif damage == "identity":
        metadata["identity"]["run"] = c["spec"]["run_name"]
    elif damage == "extra":
        (target / "extra").touch()
    else:
        metadata["nonce"] = "wrong"
    (target / "backup.json").write_text(json.dumps(metadata))
    (target / "latest.json").write_text(json.dumps(row))
    with pytest.raises(ValueError, match="SNAPSHOT"):
        namespace["snapshot_check"](c)


@pytest.mark.parametrize(
    "damage", ["archive", "manifest", "result", "target-package", "target-result", "result-venv"]
)
def test_source_guard_rejects_mismatch_existing_and_overlapping_paths(restored, damage):
    c, namespace, _metadata, _row = restored
    p = c["paths"]
    if damage == "archive":
        Path(p["archive"]).write_bytes(b"bad")
    elif damage == "manifest":
        (Path(p["package"]) / "manifest.json").write_bytes(b"bad")
    elif damage == "result":
        Path(p["result"]).mkdir()
    elif damage == "target-package":
        p["target"] = str(Path(p["package"]) / "recovery")
    elif damage == "target-result":
        p["target"] = p["result"]
    else:
        p["result"] = str(Path(p["venv"]) / "result")
    with pytest.raises(ValueError):
        namespace["source_check"](c)


def test_guard_rejects_symlink_ancestor_before_package_import(restored, monkeypatch):
    c, namespace, _metadata, _row = restored
    forbidden = Path(c["paths"]["package"]).parent
    original = Path.is_symlink
    monkeypatch.setattr(Path, "is_symlink", lambda path: path == forbidden or original(path))
    with pytest.raises(ValueError, match="UNSAFE_RECOVERY_PATH"):
        namespace["source_check"](c)
